#!/usr/bin/env node
'use strict';

/*
 * MIPS32r2 (little-endian, o32 ABI) interpreter for the doomgeneric_mips ELF.
 *
 * Loads the ELF segments into a flat address space, executes MIPS instructions
 * starting at the entry point, and services Linux syscalls (using x86_64-style
 * syscall numbers placed in $v0, as the binary was authored to do).
 *
 * File syscalls (open/read/write/close/lseek/...) are served against the real
 * host filesystem so that doom.wad is read and /tmp/frame.bmp is written.
 */

const fs = require('fs');
const path = require('path');
const os = require('os');

// ---------------------------------------------------------------------------
// Memory: a flat byte buffer covering the whole virtual address range we use.
// The ELF maps a small .text/.rodata/.data region near 0x00400000 and a ~1 GB
// .bss (mostly the static heap) up to ~0x404b1790. We allocate a single Buffer
// big enough to hold all of it and map virtual addresses to offsets.
// ---------------------------------------------------------------------------

const MEM_BASE = 0x400000;          // lowest mapped virtual address
const MEM_SIZE = 0x404c0000 - MEM_BASE; // ~1.07 GB, covers .bss end with slack
const mem = Buffer.alloc(MEM_SIZE, 0);

function memOff(va) {
  const o = va - MEM_BASE;
  if (o < 0 || o >= MEM_SIZE) {
    throw new Error(`memory access out of range: va=0x${(va>>>0).toString(16)} off=0x${o.toString(16)}`);
  }
  return o;
}

// little-endian word/halfword/byte accessors
function loadU32(va) { return mem.readUInt32LE(memOff(va)) >>> 0; }
function loadU16(va) { return mem.readUInt16LE(memOff(va)) >>> 0; }
function loadU8(va)  { return mem.readUInt8(memOff(va)); }
function loadS32(va) { return mem.readInt32LE(memOff(va)); }
function loadS16(va) { return mem.readInt16LE(memOff(va)); }
function loadS8(va)  { return mem.readInt8(memOff(va)); }
function storeU32(va, v) { mem.writeUInt32LE(v >>> 0, memOff(va)); }
function storeU16(va, v) { mem.writeUInt16LE(v & 0xffff, memOff(va)); }
function storeU8(va, v)  { mem.writeUInt8(v & 0xff, memOff(va)); }

// ---------------------------------------------------------------------------
// CPU state
// ---------------------------------------------------------------------------

const R = new Uint32Array(32);      // general registers
const HI = new Uint32Array(1);     // HI register
const LO = new Uint32Array(1);     // LO register
const FPR = new Float64Array(32);  // FP registers (as 64-bit; o32 uses pairs)
const FCR31 = { c: 0 };            // FP status/control; we only model FCC bits
let pc = 0;
let nextPc = 0;                    // for branch delay slot handling
let halted = false;

// FP condition bit (fcc0) lives in FCR31 bit 23
function fpSetCond(bit, v) { if (v) FCR31.c |= (1 << (23 + bit)); else FCR31.c &= ~(1 << (23 + bit)); }
function fpGetCond(bit) { return (FCR31.c >> (23 + bit)) & 1; }

// helpers to read/write FP as single (32) / double (64) via the o32 model:
// o32 with FR=0: $f0 and $f1 form a double pair. We store doubles in FPR[i]
// for the even register and treat the pair as the full double.
function fprGetSingle(i) {
  const buf = Buffer.alloc(4);
  buf.writeUInt32LE(R_fpr32(i), 0);
  return buf.readFloatLE(0);
}
function fprSetSingle(i, val) {
  const buf = Buffer.alloc(4);
  buf.writeFloatLE(val, 0);
  setFpr32(i, buf.readUInt32LE(0));
}
// 32-bit FP register storage kept in a parallel array for the o32 single view
const FPR32 = new Uint32Array(32);
function R_fpr32(i) { return FPR32[i] >>> 0; }
function setFpr32(i, v) { FPR32[i] = v >>> 0; }

function fprGetDouble(i) {
  // double occupies even/odd pair; reconstruct from two 32-bit halves (LE)
  const lo = R_fpr32(i);
  const hi = R_fpr32(i + 1);
  const buf = Buffer.alloc(8);
  buf.writeUInt32LE(lo, 0);
  buf.writeUInt32LE(hi, 4);
  return buf.readDoubleLE(0);
}
function fprSetDouble(i, val) {
  const buf = Buffer.alloc(8);
  buf.writeDoubleLE(val, 0);
  setFpr32(i, buf.readUInt32LE(0));
  setFpr32(i + 1, buf.readUInt32LE(4));
}

R[0] = 0; // $zero always 0

// ---------------------------------------------------------------------------
// ELF loading
// ---------------------------------------------------------------------------

function loadElf(file) {
  const data = fs.readFileSync(file);
  if (data[0] !== 0x7f || data[1] !== 0x45 || data[2] !== 0x4c || data[3] !== 0x46) {
    throw new Error('not an ELF file');
  }
  const e_class = data[4];   // 1 = 32-bit
  const e_data = data[5];    // 1 = LE
  if (e_class !== 1 || e_data !== 1) throw new Error('expected 32-bit LE ELF');
  const e_entry = data.readUInt32LE(24);
  const e_phoff = data.readUInt32LE(28);
  const e_phentsize = data.readUInt16LE(42);
  const e_phnum = data.readUInt16LE(44);

  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = data.readUInt32LE(off);
