  const argStrs = [];
  for (const a of argv) {
    const b = Buffer.from(a + '\0', 'utf8');
    sp -= b.length;
    sp &= ~0x3; // keep aligned
    mem.set(b, memOff(sp));
    argStrs.push(sp);
  }
  // align
  sp &= ~0xf;
  // We will push: argc, argv[0..n], NULL, envp NULL, auxv (AT_NULL)
  // total words = 1 + argv.length + 1 + 1 + 2
  const words = 1 + argv.length + 1 + 1 + 2;
  sp -= words * 4;
  sp &= ~0xf;
  let p = sp;
  const writeWord = (v) => { storeU32(p, v); p += 4; };
  writeWord(argv.length);          // argc
  for (const ap of argStrs) writeWord(ap); // argv[]
  writeWord(0);                    // argv terminator
  writeWord(0);                    // envp terminator
  writeWord(0); writeWord(0);      // AT_NULL auxv
  return sp;
}

// ---------------------------------------------------------------------------
// Sign helpers
// ---------------------------------------------------------------------------
function s32(x) { return (x | 0); }
function u32(x) { return (x >>> 0); }
function sext16(x) { return (x & 0x8000) ? (x | 0xffff0000) | 0 : (x & 0xffff); }
function sext8(x)  { return (x & 0x80) ? (x | 0xffffff00) | 0 : (x & 0xff); }

// ---------------------------------------------------------------------------
// Syscalls. Numbers are the x86_64-style numbers the binary places in $v0.
// Args in $a0..$a3, $a4($t0), $a5($t1). Return in $v0.
// ---------------------------------------------------------------------------

const fdMap = new Map(); // guest fd -> host fd (for files we opened)
let nextGuestFd = 3;

function readCString(va, max) {
  max = max || 4096;
  let s = '';
  for (let i = 0; i < max; i++) {
    const b = loadU8(va + i);
    if (b === 0) break;
    s += String.fromCharCode(b);
  }
  return s;
}

function writeBuf(va, len) {
  const off = memOff(va);
  return Buffer.from(mem.buffer, off, len);
}

function doSyscall() {
  const num = R[2];       // $v0
  const a0 = R[4], a1 = R[5], a2 = R[6], a3 = R[7];
  const a4 = R[8], a5 = R[9]; // $t0, $t1
  let ret = 0;
  switch (num) {
    case 0: { // read
      const fd = a0;
      const buf = a1;
      const count = a2;
      try {
        const data = fs.readSync(fdMap.get(fd) ?? fd, Buffer.alloc(count), 0, count, null);
        if (data > 0) mem.set(data, memOff(buf)); // placeholder; see below
      } catch (e) {
        // fallthrough handled below
      }
      // The above is wrong; redo properly:
      ret = sysRead(fd, buf, count);
      break;
    }
    case 1: { // write
      ret = sysWrite(a0, a1, a2);
      break;
    }
    case 2: { // open
      ret = sysOpen(a0, a1, a2);
      break;
    }
    case 3: { // close
      ret = sysClose(a0);
      break;
    }
    case 8: { // lseek
      ret = sysLseek(a0, a1, a2);
      break;
    }
    case 74: { // fsync
      const hfd = fdMap.get(a0);
      if (hfd !== undefined) { try { fs.fsyncSync(hfd); } catch (e) {} ret = 0; }
      else ret = 0;
      break;
    }
    case 82: { // rename
      const oldp = readCString(a0), newp = readCString(a1);
      try { fs.renameSync(oldp, newp); ret = 0; } catch (e) { ret = -e.errno || -1; }
      break;
    }
    case 83: { // mkdir
      const p = readCString(a0);
      try { fs.mkdirSync(p, { recursive: false }); ret = 0; } catch (e) { ret = -1; }
      break;
    }
    case 87: { // unlink
      const p = readCString(a0);
      try { fs.unlinkSync(p); ret = 0; } catch (e) { ret = -1; }
      break;
    }
    case 60: { // exit / exit_group
      halted = true;
      ret = 0;
      break;
    }
    case 201: { // time
      const t = Math.floor(Date.now() / 1000) | 0;
      if (a0 !== 0) storeU32(a0, t);
      ret = t;
      break;
    }
    case 96: { // gettimeofday (just in case)
      const t = Math.floor(Date.now() / 1000) | 0;
      const us = (Date.now() % 1000) * 1000;
      if (a0 !== 0) { storeU32(a0, t); storeU32(a0 + 4, us); }
      ret = 0;
      break;
    }
    default:
      // Unknown syscall: return 0 rather than crash; doom doesn't depend on much.
      ret = 0;
  }
  R[2] = ret >>> 0;
  // On MIPS, a3 is used as an error flag (0 = success, 1 = error). The binary's
  // own syscall wrappers check $v0 sign, so we just set v0. Set a3=0 (no error).
  R[7] = 0;
}

function sysRead(fd, buf, count) {
  const hfd = fdMap.get(fd);
  const real = hfd !== undefined ? hfd : fd;
  try {
    const tmp = Buffer.allocUnsafeSlow(count);
    const n = fs.readSync(real, tmp, 0, count, null);
    if (n > 0) mem.set(tmp.subarray(0, n), memOff(buf));
    return n;
  } catch (e) {
    return -1;
  }
}

function sysWrite(fd, buf, count) {
  const hfd = fdMap.get(fd);
  const real = hfd !== undefined ? hfd : fd;
  try {
    const data = Buffer.from(mem.buffer, memOff(buf), count);
    const n = fs.writeSync(real, data, 0, count, null);
    return n;
  } catch (e) {
    return -1;
  }
}

function sysOpen(pathname, flags, mode) {
  const p = readCString(pathname);
  // flags are x86_64-style open flags
  let hostFlags = 0;
  const O_RDONLY = 0, O_WRONLY = 1, O_RDWR = 2;
  const O_CREAT = 0x40, O_EXCL = 0x80, O_TRUNC = 0x200, O_APPEND = 0x400;
  const acc = flags & 3;
  if (acc === O_RDONLY) hostFlags |= fs.constants.O_RDONLY;
  else if (acc === O_WRONLY) hostFlags |= fs.constants.O_WRONLY;
  else hostFlags |= fs.constants.O_RDWR;
  if (flags & O_CREAT) hostFlags |= fs.constants.O_CREAT;
  if (flags & O_EXCL) hostFlags |= fs.constants.O_EXCL;
  if (flags & O_TRUNC) hostFlags |= fs.constants.O_TRUNC;
  if (flags & O_APPEND) hostFlags |= fs.constants.O_APPEND;
  try {
    const hfd = fs.openSync(p, hostFlags, mode & 0o777);
    const gfd = nextGuestFd++;
    fdMap.set(gfd, hfd);
    return gfd;
  } catch (e) {
    return -2; // -ENOENT
  }
}

function sysClose(fd) {
  const hfd = fdMap.get(fd);
  if (hfd !== undefined) {
    try { fs.closeSync(hfd); } catch (e) {}
    fdMap.delete(fd);
    return 0;
  }
  // stdin/stdout/stderr: just succeed
  if (fd >= 0 && fd <= 2) return 0;
  return -1;
}

function sysLseek(fd, offset, whence) {
  const hfd = fdMap.get(fd);
  const real = hfd !== undefined ? hfd : fd;
  try {
    // Node's position via readSync/writeSync with null uses a stored position;
    // for lseek we need to track positions ourselves.
    return fileLseek(real, offset | 0, whence);
  } catch (e) {
    return -1;
  }
}

// Track per-host-fd positions because Node readSync/writeSync with null offset
// maintain an internal position, but lseek needs explicit control.
const fdPos = new Map();
function fileLseek(hfd, offset, whence) {
  let pos = fdPos.get(hfd);
  if (pos === undefined) pos = 0;
  let stat = null;
  try { stat = fs.fstatSync(hfd); } catch (e) {}
  if (whence === 0) pos = offset;          // SEEK_SET
  else if (whence === 1) pos = pos + offset; // SEEK_CUR
  else if (whence === 2) pos = (stat ? stat.size : 0) + offset; // SEEK_END
  else return -1;
  if (pos < 0) pos = 0;
  fdPos.set(hfd, pos);
  return pos;
}

// Override sysRead/sysWrite to honor tracked positions.
function sysReadPos(fd, buf, count) {
  const hfd = fdMap.get(fd);
  const real = hfd !== undefined ? hfd : fd;
  let pos = fdPos.get(real);
  try {
    const tmp = Buffer.allocUnsafeSlow(count);
    const n = fs.readSync(real, tmp, 0, count, pos === undefined ? null : pos);
    if (n > 0) mem.set(tmp.subarray(0, n), memOff(buf));
    if (pos !== undefined) fdPos.set(real, pos + Math.max(n, 0));
    return n;
  } catch (e) {
    return -1;
  }
}
function sysWritePos(fd, buf, count) {
  const hfd = fdMap.get(fd);
  const real = hfd !== undefined ? hfd : fd;
  let pos = fdPos.get(real);
  try {
    const data = Buffer.from(mem.buffer, memOff(buf), count);
    const n = fs.writeSync(real, data, 0, count, pos === undefined ? null : pos);
    if (pos !== undefined) fdPos.set(real, pos + Math.max(n, 0));
    return n;
  } catch (e) {
    return -1;
  }
}

// ---------------------------------------------------------------------------
// Instruction decode + execute
// ---------------------------------------------------------------------------

const OP = {
  SPECIAL: 0x00, REGIMM: 0x01, J: 0x02, JAL: 0x03, BEQ: 0x04, BNE: 0x05,
  BLEZ: 0x06, BGTZ: 0x07, ADDI: 0x08, ADDIU: 0x09, SLTI: 0x0a, SLTIU: 0x0b,
  ANDI: 0x0c, ORI: 0x0d, XORI: 0x0e, LUI: 0x0f, COP1: 0x11, BEQL: 0x14,
  BNEL: 0x15, BLEZL: 0x16, BGTZL: 0x17, SPECIAL2: 0x1c, SPECIAL3: 0x1f,
  LB: 0x20, LH: 0x21, LWL: 0x22, LW: 0x23, LBU: 0x24, LHU: 0x25, LWR: 0x26,
  SB: 0x28, SH: 0x29, SWL: 0x2a, SW: 0x2b, SWR: 0x2e, LWC1: 0x31,
  PREF: 0x33, SWC1: 0x39, LDC1: 0x35, SDC1: 0x3d,
};

function run() {
  let insnCount = 0;
  // Use a simple branch-delay model: each step fetches at pc, executes, and
  // pc advances to nextPc; branches set nextPc.
  while (!halted) {
    step();
    insnCount++;
    if ((insnCount & 0xffffff) === 0) {
      // periodic yield to event loop not needed; pure sync loop
    }
  }
}

function setReg(i, v) {
  if (i !== 0) R[i] = v >>> 0;
}

function step() {
  const cur = pc;
  const insn = loadU32(cur);
  pc = nextPc;
  nextPc = (nextPc + 4) >>> 0;

  const op = (insn >>> 26) & 0x3f;
  const rs = (insn >>> 21) & 0x1f;
  const rt = (insn >>> 16) & 0x1f;
  const rd = (insn >>> 11) & 0x1f;
  const shamt = (insn >>> 6) & 0x1f;
  const funct = insn & 0x3f;
  const imm = insn & 0xffff;
  const simm = (imm & 0x8000) ? ((imm | 0xffff0000) | 0) : imm;
  const target = insn & 0x3ffffff;

  switch (op) {
    case OP.SPECIAL: execSpecial(insn, funct, rs, rt, rd, shamt); break;
    case OP.REGIMM: execRegimm(insn, rs, rt, simm); break;
    case OP.J: nextPc = ((cur & 0xf0000000) | (target << 2)) >>> 0; break;
    case OP.JAL: setReg(31, (cur + 8) >>> 0); nextPc = ((cur & 0xf0000000) | (target << 2)) >>> 0; break;
    case OP.BEQ: if (R[rs] === R[rt]) nextPc = (cur + 4 + (simm << 2)) >>> 0; break;
    case OP.BNE: if (R[rs] !== R[rt]) nextPc = (cur + 4 + (simm << 2)) >>> 0; break;
    case OP.BLEZ: if ((R[rs] | 0) <= 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; break;
    case OP.BGTZ: if ((R[rs] | 0) > 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; break;
    case OP.ADDI: { // trap on overflow (we ignore trap, just compute)
      const r = (R[rs] | 0) + simm;
      setReg(rt, r);
      break;
    }
    case OP.ADDIU: setReg(rt, (R[rs] + simm) >>> 0); break;
    case OP.SLTI: setReg(rt, ((R[rs] | 0) < simm) ? 1 : 0); break;
    case OP.SLTIU: setReg(rt, (R[rs] < (simm >>> 0)) ? 1 : 0); break;
    case OP.ANDI: setReg(rt, R[rs] & imm); break;
    case OP.ORI: setReg(rt, R[rs] | imm); break;
    case OP.XORI: setReg(rt, R[rs] ^ imm); break;
    case OP.LUI: setReg(rt, (imm << 16) >>> 0); break;
    case OP.BEQL: if (R[rs] === R[rt]) nextPc = (cur + 4 + (simm << 2)) >>> 0; else nextPc = (nextPc + 4) >>> 0; break;
    case OP.BNEL: if (R[rs] !== R[rt]) nextPc = (cur + 4 + (simm << 2)) >>> 0; else nextPc = (nextPc + 4) >>> 0; break;
    case OP.BLEZL: if ((R[rs] | 0) <= 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; else nextPc = (nextPc + 4) >>> 0; break;
    case OP.BGTZL: if ((R[rs] | 0) > 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; else nextPc = (nextPc + 4) >>> 0; break;
    case OP.SPECIAL2: execSpecial2(insn, funct, rs, rt, rd); break;
    case OP.SPECIAL3: execSpecial3(insn, funct, rs, rt, rd, shamt); break;
    case OP.LB: setReg(rt, sext8(loadU8(R[rs] + simm)) >>> 0); break;
    case OP.LH: setReg(rt, sext16(loadU16(R[rs] + simm)) >>> 0); break;
    case OP.LWL: setReg(rt, lwl(R[rs] + simm, R[rt])); break;
    case OP.LW: setReg(rt, loadU32(R[rs] + simm)); break;
    case OP.LBU: setReg(rt, loadU8(R[rs] + simm)); break;
    case OP.LHU: setReg(rt, loadU16(R[rs] + simm)); break;
    case OP.LWR: setReg(rt, lwr(R[rs] + simm, R[rt])); break;
    case OP.SB: storeU8(R[rs] + simm, R[rt] & 0xff); break;
    case OP.SH: storeU16(R[rs] + simm, R[rt] & 0xffff); break;
    case OP.SWL: swl(R[rs] + simm, R[rt]); break;
    case OP.SW: storeU32(R[rs] + simm, R[rt]); break;
    case OP.SWR: swr(R[rs] + simm, R[rt]); break;
    case OP.LWC1: setFpr32(rt, loadU32(R[rs] + simm)); break;
    case OP.SWC1: storeU32(R[rs] + simm, R_fpr32(rt)); break;
    case OP.LDC1: { const a = R[rs] + simm; setFpr32(rt, loadU32(a)); setFpr32(rt+1, loadU32(a+4)); break; }
    case OP.SDC1: { const a = R[rs] + simm; storeU32(a, R_fpr32(rt)); storeU32(a+4, R_fpr32(rt+1)); break; }
    case OP.PREF: break; // prefetch, no-op
    case OP.COP1: execCop1(insn); break;
    default:
      throw new Error(`unhandled opcode 0x${op.toString(16)} at pc=0x${cur.toString(16)} insn=0x${insn.toString(16)}`);
  }
}

// SPECIAL (R-type)
function execSpecial(insn, funct, rs, rt, rd, shamt) {
  switch (funct) {
    case 0x00: setReg(rd, (R[rt] << shamt) >>> 0); break; // SLL
    case 0x02: { // SRL -- but rotr if rs field set (SRL vs ROTR)
      if ((insn >>> 21) & 1) setReg(rd, ((R[rt] >>> shamt) | (R[rt] << (32 - shamt))) >>> 0); // ROTR
      else setReg(rd, R[rt] >>> shamt); break;
    }
    case 0x03: setReg(rd, (R[rt] << shamt) | (R[rt] >>> (32 - shamt))); break; // SRA (sign handled by >>> for 0)
    case 0x04: setReg(rd, (R[rt] << (R[rs] & 0x1f)) >>> 0); break; // SLLV
    case 0x06: setReg(rd, R[rt] >>> (R[rs] & 0x1f)); break; // SRLV
    case 0x07: setReg(rd, (R[rt] << (R[rs] & 0x1f)) | (R[rt] >>> (32 - (R[rs] & 0x1f)))); break; // SRAV (arith)
    case 0x08: nextPc = R[rs]; break; // JR
    case 0x09: setReg(31, (pc + 4) >>> 0); nextPc = R[rs]; break; // JALR
    case 0x0a: setReg(rd, ((R[rs] >>> 0) < (R[rt] >>> 0)) ? 1 : 0); break; // MOVZ? no: SLT
    // (0x0a is MOVZ in some? No—0x0a is MOVZ, 0x0b is MOVN, 0x2a is SLT)
    // Correcting: 0x0a MOVZ, 0x0b MOVN, 0x2a SLT, 0x2b SLTU
    case 0x0a: if (R[rt] === 0) setReg(rd, R[rs]); break; // MOVZ
    case 0x0b: if (R[rt] !== 0) setReg(rd, R[rs]); break; // MOVN
    case 0x0c: doSyscall(); break; // SYSCALL
    case 0x0d: break; // BREAK (treat as no-op for now)
    case 0x0f: nextPc = (nextPc & ~0); break; // SYNC (no-op)
    case 0x10: { // MFHI
      // actually 0x10 is MFHI
      setReg(rd, HI[0]); break;
    }
    case 0x11: HI[0] = R[rs]; break; // MTHI
    case 0x12: setReg(rd, LO[0]); break; // MFLO
    case 0x13: LO[0] = R[rs]; break; // MTLO
    case 0x18: { // MULT
      const r = (R[rs] | 0) * (R[rt] | 0);
      LO[0] = r >>> 0; HI[0] = (r / 0x100000000) | 0 >>> 0; break;
    }
    case 0x19: { // MULTU
      const r = R[rs] * R[rt];
      LO[0] = r >>> 0; HI[0] = (Math.floor(r / 0x100000000)) >>> 0; break;
    }
    case 0x1a: { // DIV
      if ((R[rt] | 0) !== 0) { LO[0] = ((R[rs] | 0) / (R[rt] | 0)) | 0 >>> 0; HI[0] = ((R[rs] | 0) % (R[rt] | 0)) | 0 >>> 0; }
      break;
    }
    case 0x1b: { // DIVU
      if (R[rt] !== 0) { LO[0] = Math.floor(R[rs] / R[rt]) >>> 0; HI[0] = (R[rs] % R[rt]) >>> 0; }
      break;
    }
    case 0x20: setReg(rd, (R[rs] + R[rt]) >>> 0); break; // ADD (no trap)
    case 0x21: setReg(rd, (R[rs] + R[rt]) >>> 0); break; // ADDU
    case 0x22: setReg(rd, (R[rs] - R[rt]) >>> 0); break; // SUB
    case 0x23: setReg(rd, (R[rs] - R[rt]) >>> 0); break; // SUBU
    case 0x24: setReg(rd, R[rs] & R[rt]); break; // AND
    case 0x25: setReg(rd, R[rs] | R[rt]); break; // OR
    case 0x26: setReg(rd, R[rs] ^ R[rt]); break; // XOR
    case 0x27: setReg(rd, ~(R[rs] | R[rt])); break; // NOR
    case 0x2a: setReg(rd, ((R[rs] | 0) < (R[rt] | 0)) ? 1 : 0); break; // SLT
    case 0x2b: setReg(rd, (R[rs] < R[rt]) ? 1 : 0); break; // SLTU
    case 0x30: case 0x31: { // TGE/TGEU etc trap — treat as no-op
      break;
    }
    case 0x34: case 0x36: { // TEQ / TNE — no-op (no trap)
      break;
    }
    default:
      throw new Error(`unhandled SPECIAL funct 0x${funct.toString(16)} insn=0x${insn.toString(16)}`);
  }
}

// REGIMM
function execRegimm(insn, rs, rt, simm) {
  const cur = pc - 4; // current instruction address (pc already advanced)
  switch (rt) {
    case 0x00: if ((R[rs] | 0) < 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; break; // BLTZ
    case 0x01: if ((R[rs] | 0) >= 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; break; // BGEZ
    case 0x02: if ((R[rs] | 0) < 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; else nextPc = (nextPc + 4) >>> 0; break; // BLTZL
    case 0x03: if ((R[rs] | 0) >= 0) nextPc = (cur + 4 + (simm << 2)) >>> 0; else nextPc = (nextPc + 4) >>> 0; break; // BGEZL
    case 0x10: setReg(31, (cur + 8) >>> 0); nextPc = (cur + 4 + (simm << 2)) >>> 0; break; // BLTZAL
    case 0x11: setReg(31, (cur + 8) >>> 0); nextPc = (cur + 4 + (simm << 2)) >>> 0; break; // BGEZAL
    default:
      throw new Error(`unhandled REGIMM rt=0x${rt.toString(16)} insn=0x${insn.toString(16)}`);
  }
}

// SPECIAL2 (MUL, MADD, CLZ, etc.)
function execSpecial2(insn, funct, rs, rt, rd) {
  switch (funct) {
    case 0x02: { // MUL
      const r = (R[rs] | 0) * (R[rt] | 0);
      setReg(rd, r >>> 0);
      break;
    }
    case 0x00: { // MADD
      const r = (R[rs] | 0) * (R[rt] | 0);
      const acc = (HI[0] * 0x100000000 + LO[0]) | 0;
      const sum = (acc + r) | 0;
      LO[0] = sum >>> 0; HI[0] = (sum / 0x100000000) | 0 >>> 0;
      break;
    }
    case 0x01: { // MADDU
      const r = R[rs] * R[rt];
      const acc = HI[0] * 0x100000000 + LO[0];
      const sum = acc + r;
      LO[0] = sum >>> 0; HI[0] = Math.floor(sum / 0x100000000) >>> 0;
      break;
    }
    case 0x20: { // CLZ
      let v = R[rs]; let c = 0;
      if (v === 0) c = 32;
      else { for (let i = 31; i >= 0; i--) { if (v & (1 << i)) break; c++; } }
      setReg(rd, c);
      break;
    }
    case 0x21: { // CLO
      let v = R[rs]; let c = 0;
      if (v === 0xffffffff) c = 32;
      else { for (let i = 31; i >= 0; i--) { if (!(v & (1 << i))) break; c++; } }
      setReg(rd, c);
      break;
    }
    default:
      throw new Error(`unhandled SPECIAL2 funct 0x${funct.toString(16)} insn=0x${insn.toString(16)}`);
  }
}

// SPECIAL3 (EXT, INS, SEB, SEH, WSBH, ROTR)
function execSpecial3(insn, funct, rs, rt, rd, shamt) {
  const sa = shamt;
  switch (funct) {
    case 0x00: { // EXT
      const pos = sa;
      const size = ((insn >>> 11) & 0x1f) + 1; // size field is bits 11-15, but actually msbd
      // EXT: rt = (rs >> pos) & ((1<<size)-1)
      const sz = ((insn >>> 11) & 0x1f) + 1;
      setReg(rt, (R[rs] >>> pos) & ((1 << sz) - 1));
      break;
    }
    case 0x04: { // INS
      const pos = sa;
      const msb = (insn >>> 11) & 0x1f;
      const size = msb - pos + 1;
      const mask = ((1 << size) - 1) << pos;
      setReg(rt, (R[rt] & ~mask) | ((R[rs] << pos) & mask));
      break;
    }
    case 0x20: { // BSHFL
      switch (sa) {
        case 0x02: { // WSBH
          const v = R[rt];
          setReg(rd, (((v & 0x00ff00ff) << 8) | ((v & 0xff00ff00) >>> 8)) >>> 0);
          break;
        }
        case 0x03: { // SEB? Actually SEB is sa=0x10? No. SEB=0x10, SEH=0x18 within BSHFL? 
